g=[[1]*30 for _ in range(30)]
# panel backgrounds
for r0 in (1,9,16):
    for c0 in (1,10,20):
        for r in range(r0,r0+6):
            for c in range(c0,c0+6): g[r][c]=8
# centers / tile labels
labels=[[2,4,3],[3,6,9],[9,4,5]]
rstarts=[1,9,16]; cstarts=[1,10,20]
for rr in range(3):
    for cc in range(3):
        color=labels[rr][cc]
        for r in range(rstarts[rr]+2,rstarts[rr]+4):
            for c in range(cstarts[cc]+2,cstarts[cc]+4): g[r][c]=color
# key row
key=[2,4,3,9,5,4,6,3,9]
for c,x in enumerate(key): g[28][2*c+1]=x
# path determined by key occurrence matching / orth adjacency
path=[(0,0),(0,1),(0,2),(1,2),(2,2),(2,1),(1,1),(1,0),(2,0)]
for (ra,ca),(rb,cb) in zip(path,path[1:]):
    color=labels[ra][ca]
    ar,ac=rstarts[ra]+2,cstarts[ca]+2
    br,bc=rstarts[rb]+2,cstarts[cb]+2
    if ra==rb:
        lo,hi=sorted((ac+1,bc+1)) # range start after square's left? Need between square extents: anchors columns ac and bc, each 2 wide
        # fill columns between end of left square and start of right square
        for r in (ar,ar+1):
            for c in range(min(ac,bc)+2,max(ac,bc)):
                if g[r][c]==8: g[r][c]=color
    else:
        for c in (ac,ac+1):
            for r in range(min(ar,br)+2,max(ar,br)):
                if g[r][c]==8: g[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in g))

# rebuild base grid
out=[[1]*30 for _ in range(30)]
for r0 in (1,9,16):
    for c0 in (1,10,20):
        for r in range(r0,r0+6):
            for c in range(c0,c0+6): out[r][c]=8
for rr in range(3):
    for cc in range(3):
        for r in range(rstarts[rr]+2,rstarts[rr]+4):
            for c in range(cstarts[cc]+2,cstarts[cc]+4): out[r][c]=labels[rr][cc]
for c,x in enumerate(key): out[28][2*c+1]=x
# paint only the exterior background (1) gaps between panel boxes
for (ra,ca),(rb,cb) in zip(path,path[1:]):
    color=labels[ra][ca]
    if ra==rb:
        left=min(ca,cb); right=max(ca,cb)
        gap=range(cstarts[left]+6,cstarts[right])
        for r in range(rstarts[ra]+2,rstarts[ra]+4):
            for c in gap:
                if out[r][c]==1: out[r][c]=color
    else:
        top=min(ra,rb); bottom=max(ra,rb)
        gap=range(rstarts[top]+6,rstarts[bottom])
        for c in range(cstarts[ca]+2,cstarts[ca]+4):
            for r in gap:
                if out[r][c]==1: out[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in out))
